class Nokta:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __str__(self):
        return f"({self.x}, {self.y})"

print(Nokta(2, 3))

class Para:
    def __init__(self, tl):
        self.tl = tl
    def __eq__(self, diger):
        return self.tl == diger.tl
    def __lt__(self, diger):
        return self.tl < diger.tl

print(Para(5) == Para(5), Para(3) < Para(1))

class Raf:
    def __init__(self, kitaplar):
        self.kitaplar = kitaplar
    def __len__(self):
        return len(self.kitaplar)
    def __getitem__(self, i):
        return self.kitaplar[i]

r = Raf(["Sefiller", "Martı"])
print(len(r), r[1])

class Vektor:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __add__(self, o):
        return Vektor(self.x + o.x, self.y + o.y)

v = Vektor(1, 2) + Vektor(3, 4)
print(v.x, v.y)

